 159	 return new Promise((resolve, reject) => {
 160	 let templateUrl = constants.remote.templateUrl.replace('{template}', template);
 161	 fs.mkdirSync('.tmp', { recursive: true });
 162	 const zipFilename = '.tmp/template.zip';
