 181	 await downloadBinariesFromRelease(latest);
 182	 utils.log('Finalizing and cleaning temp. files.');
 183	 if (!fse.existsSync('bin'))
 184	 fse.mkdirSync('bin');
 185	
 186	 for (let platform in constants.files.binaries) {
