 1	const fs = require('fs');
 2	const fse = require('fs-extra');
 3	const { https } = require('follow-redirects');
 4	const constants = require('../constants');
 5	const config = require('./config');
 6	const utils = require('../utils');
 7	const zl = require('zip-lib');
 8	
 9	let cachedLatestClientVersion = null;
 10	
 11	
 12	let getRemoteLatestVersion = (repo) => {
 13	 return new Promise((resolve, reject) => {
 14	 let opt = {
 15	 headers: { 'User-Agent': 'Neutralinojs CLI' }
 16	 };
 17	 https.get(constants.remote.releasesApiUrl.replace('{repo}', repo), opt, function (response) {
 18	 let body = '';
 19	 response.on('data', (data) => body += data);
 20	 response.on('end', () => {
 21	 if (response.statusCode != 200) {
 22	 return reject();
 23	 }
 24	 let apiRes = JSON.parse(body);
 25	 let version = apiRes.tag_name.replace('v', '');
 26	 resolve(version);
 27	 });
 28	 response.on('error', () => {
 29	 reject();
 30	 });
 31	 })
 32	 .on('error', () => {
 33	 reject();
 34	 });
 35	 });
 36	}
 37	
 38	let getLatestVersion = (repo) => {
 39	 return new Promise((resolve, reject) => {
 40	 function fallback() {
 41	 utils.warn('Unable to fetch the latest version tag from GitHub. Using nightly releases...');
 42	 resolve('nightly');
 43	 }
 44	
 45	 getRemoteLatestVersion(repo)
 46	 .then((version) => {
 47	 utils.log(`Found the latest release tag ${utils.getVersionTag(version)} for ${repo}...`);
 48	 resolve(version);
 49	 })
 50	 .catch((error) => fallback());
 51	 });
 52	}
 53	
 54	let getScriptExtension = () => {
 55	 const configObj = config.get();
 56	 let clientLibrary = configObj.cli.clientLibrary;
 57	 return clientLibrary.includes('.mjs') ? 'mjs' : 'js';
 58	}
 59	
 60	let getBinaryDownloadUrl = async (latest) => {
 61	 const configObj = config.get();
 62	 let version = configObj.cli.binaryVersion;
 63	
 64	 if (!version || latest) {
 65	 version = await getLatestVersion('neutralinojs');
 66	 config.update('cli.binaryVersion', version);
 67	 }
 68	 return constants.remote.binariesUrl
 69	 .replace(/\{tag\}/g, utils.getVersionTag(version));
 70	}
 71	
 72	let getClientDownloadUrl = async (latest, types = false) => {
 73	 const configObj = config.get();
 74	 let version = configObj.cli.clientVersion;
 75	
 76	 if (!version || latest) {
 77	 if (cachedLatestClientVersion) {
 78	 version = cachedLatestClientVersion;
 79	 }
 80	 else {
 81	 version = await getLatestVersion('neutralino.js');
 82	 }
 83	 cachedLatestClientVersion = version;
 84	 config.update('cli.clientVersion', version);
 85	 }
 86	
 87	 let scriptUrl = constants.remote.clientUrlPrefix + (types ? 'd.ts' : getScriptExtension());
 88	 return scriptUrl
 89	 .replace(/\{tag\}/g, utils.getVersionTag(version));
 90	}
 91	
 92	let getTypesDownloadUrl = (latest) => {
 93	 return getClientDownloadUrl(latest, true);
 94	}
 95	
 96	let getRepoNameFromTemplate = (template) => {
 97	 return template.split('/')[1];
 98	}
 99	
 100	let downloadBinariesFromRelease = (latest) => {
 101	 return new Promise((resolve, reject) => {
 102	 fs.mkdirSync('.tmp', { recursive: true });
 103	 const zipFilename = '.tmp/binaries.zip';
 104	 const file = fs.createWriteStream(zipFilename);
 105	 utils.log('Downloading Neutralinojs binaries..');
 106	 getBinaryDownloadUrl(latest)
 107	 .then((url) => {
 108	 https.get(url, function (response) {
 109	 response.pipe(file);
 110	 response.on('end', () => {
 111	 utils.log('Extracting binaries.zip file...');
 112	 zl.extract(zipFilename, '.tmp/')
 113	 .then(() => resolve())
 114	 .catch((e) => reject(e));
 115	 });
 116	 });
 117	 });
 118	 });
 119	}
 120	
 121	let downloadClientFromRelease = (latest) => {
 122	 return new Promise((resolve, reject) => {
 123	 fs.mkdirSync('.tmp', { recursive: true });
 124	 const file = fs.createWriteStream('.tmp/neutralino.' + getScriptExtension());
 125	 utils.log('Downloading the Neutralinojs client..');
 126	 getClientDownloadUrl(latest)
 127	 .then((url) => {
 128	 https.get(url, function (response) {
 129	 response.pipe(file);
 130	 file.on('finish', () => {
 131	 file.close();
 132	 resolve();
 133	 });
 134	 });
 135	 });
 136	 });
 137	}
 138	
 139	let downloadTypesFromRelease = (latest) => {
 140	 return new Promise((resolve, reject) => {
 141	 fs.mkdirSync('.tmp', { recursive: true });
