 151	 resolve();
 152	 });
 153	 });
 154	 });
 155	 });
 156	}
 157	
 158	module.exports.downloadTemplate = (template) => {
 159	 return new Promise((resolve, reject) => {
 160	 let templateUrl = constants.remote.templateUrl.replace('{template}', template);
 161	 fs.mkdirSync('.tmp', { recursive: true });
 162	 const zipFilename = '.tmp/template.zip';
 163	 const file = fs.createWriteStream(zipFilename);
 164	 https.get(templateUrl, function (response) {
 165	 response.pipe(file);
 166	 response.on('end', () => {
 167	 utils.log('Extracting template zip file...');
 168	 zl.extract(zipFilename, '.tmp/')
 169	 .then(() => {
