 171	 utils.clearDirectory('.tmp');
 172	 resolve();
 173	 })
 174	 .catch((e) => reject(e));
 175	 });
 176	 });
 177	 });
 178	}
 179	
 180	module.exports.downloadAndUpdateBinaries = async (latest = false) => {
 181	 await downloadBinariesFromRelease(latest);
 182	 utils.log('Finalizing and cleaning temp. files.');
 183	 if (!fse.existsSync('bin'))
 184	 fse.mkdirSync('bin');
 185	
 186	 for (let platform in constants.files.binaries) {
 187	 for (let arch in constants.files.binaries[platform]) {
 188	 let binaryFile = constants.files.binaries[platform][arch];
 189	 if (fse.existsSync(`.tmp/${binaryFile}`)) {
 190	 fse.copySync(`.tmp/${binaryFile}`, `bin/${binaryFile}`);
 191	 // Ensure that correct permissions are set
 192	 // Non-applicable on Windows platform and not needed for Windows executables
 193	 if (process.platform !== 'win32' && platform !== 'win32') {
 194	 fse.chmodSync(`bin/${binaryFile}`, '755');
 195	 }
 196	 }
 197	 }
 198	 }
 199	
 200	 for (let dependency of constants.files.dependencies) {
 201	 fse.copySync(`.tmp/${dependency}`, `bin/${dependency}`);
 202	 }
 203	 utils.clearDirectory('.tmp');
 204	}
 205	
 206	module.exports.downloadAndUpdateClient = async (latest = false) => {
 207	 const configObj = config.get();
 208	 if (!configObj.cli.clientLibrary) {
 209	 utils.log(`neu CLI won't download the client library --` +
 210	 ` download @neutralinojs/lib from your Node package manager.`);
 211	 return;
 212	 }
 213	 const clientLibrary = utils.trimPath(configObj.cli.clientLibrary);
 214	 await downloadClientFromRelease(latest);
 215	 await downloadTypesFromRelease(latest);
 216	 utils.log('Finalizing and cleaning temp. files...');
 217	 fse.copySync(`.tmp/${constants.files.clientLibraryPrefix + getScriptExtension()}`
 218	 , `./${clientLibrary}`);
 219	 fse.copySync(`.tmp/neutralino.d.ts`
 220	 , `./${clientLibrary.replace(/[.][a-z]*$/, '.d.ts')}`);
 221	 utils.clearDirectory('.tmp');
 222	}
 223	
 224	module.exports.isValidTemplate = (template) => {
 225	 return new Promise((resolve) => {
 226	 let opt = {
 227	 headers: { 'User-Agent': 'Neutralinojs CLI' }
 228	 };
 229	
 230	 function fallback() {
 231	 utils.warn('Unable to check the template validity via the GitHub API. Assuming that the template is valid...');
 232	 resolve(true);
 233	 }
 234	
 235	 https.get(constants.remote.templateCheckUrl.replace('{template}', template), opt,
 236	 function (response) {
 237	 response.req.abort();
 238	 if(response.statusCode == 200) {
 239	 resolve(true);
 240	 }
 241	 else if(response.statusCode == 404) {
 242	 resolve(false);
 243	 }
 244	 else {
 245	 fallback();
 246	 }
 247	 })
 248	 .on('error', (e) => {
 249	 fallback();
 250	 });
 251	 });
 252	
 253	}
 254	
 255	module.exports.getRemoteLatestVersion = getRemoteLatestVersion;
