 1	const { execSync } = require('child_process');
 2	const fs = require('fs');
 3	
 4	function run(command) {
 5	 let output = null;
 6	 let err = null;
 7	 let statusCode = 0;
 8	
 9	 try {
 10	 output = execSync(command);
 11	 }
 12	 catch(error) {
 13	 statusCode = error.status;
 14	 err = error;
 15	 }
 16	 finally {
 17	 return { 
 18	 error: decodeUTF8(err), 
 19	 data : decodeUTF8(output), 
 20	 status : statusCode
 21	 };
 22	 }
 23	}
 24	
 25	function decodeUTF8(decode) {
 26	 return decode ? decode.toString('utf8') : null;
 27	}
 28	
 29	function cleanup() {
 30	 try {
 31	 fs.rmSync('./test-app',{ recursive: true});
 32	 fs.rmSync('./test-template-app',{ recursive: true});
 33	 }
 34	 catch(err) {
 35	 // ignore
 36	 }
 37	}
 38	
 39	function updateVersions(binaryVersion, clientVersion) {
 40	 const file = 'neutralino.config.json';
 41	 const config = JSON.parse(fs.readFileSync(file));
 42	 
 43	 config['cli']['binaryVersion'] = binaryVersion;
 44	 config['cli']['clientVersion'] = clientVersion;
 45	 fs.writeFileSync(file, JSON.stringify(config, null, 2));
 46	}
 47	
 48	module.exports = {
 49	 cleanup,
 50	 updateVersions,
