 10	module.exports.registerPlugins = async (program, modules) => {
 11	 if(!config.has('plugins'))
 12	 return;
 13	 for(let pluginName of config.get('plugins')) {
 14	 try {
 15	 let plugin = require(pluginName);
 16	 if(plugin.register && plugin.command)
 17	 plugin.register(program.command(plugin.command), modules);
 18	 else
