 34	let add = (pluginName) => {
 35	 return new Promise((resolve, reject) => {
 36	 let plugins = [];
 37	 if(config.has('plugins'))
 38	 plugins = config.get('plugins');
 39	 if(!isPluginInstalled(pluginName)) {
 40	 exec(`cd ${NEU_ROOT} && npm install ${pluginName}`, (err, stdout, stderr) => {
 41	 if(err) {
 42	 reject(stderr);
 43	 }
 44	 else if(!plugins.includes(pluginName)) {
 45	 plugins.push(pluginName);
 46	 config.set('plugins', plugins);
 47	 }
 48	 resolve();
 49	 });
