 11	 }
 12	 catch(error) {
 13	 statusCode = error.status;
 14	 err = error;
 15	 }
 16	 finally {
 17	 return { 
 18	 error: decodeUTF8(err), 
 19	 data : decodeUTF8(output), 
 20	 status : statusCode
 21	 };
 22	 }
 23	}
 24	
 25	function decodeUTF8(decode) {
 26	 return decode ? decode.toString('utf8') : null;
 27	}
