start":"10928","char_end":"11550","blob_name":"87b6c5c7fde27661e815d3fa00ab816475b69c94d7022d640b0f4d08d6d86019","file":{"repoRoot":"","pathName":"src/modules/downloader.js"}}]},{"status":"success","request_id":"ab2f385f-6f7a-44ef-a295-8d661a2a9c0a","request_message":"If someone had installed the original package, how can the user change to my package instead?","rich_text_json_repr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If someone had installed the original package, how can the user change to my package instead?"}]}]},"mentioned_items":[],"structured_output_nodes":[{"id":1,"type":0,"content":"Here's how users can switch from the original `@neutralinojs/neu` to your enhanced version:

## 1. Uninstall the original package
```bash
npm uninstall -g @neutralinojs/neu
```

## 2. Install your enhanced version
```bash
npm install -g @yourusername/neu
```

## 3. Verify the switch worked
```bash
neu --version
which neu # On Unix/Linux/macOS
where neu # On Windows
```

## Important considerations:

### For existing projects
Users don't need to change anything in their existing Neutralinojs projects. Your package provides the same `neu` command with the same functionality, plus your enhancements.

### If they want to switch back
```bash
npm uninstall -g @yourusername/neu
npm install -g @neutralinojs/neu
```

### For teams/CI environments
You might want to provide clear migration instructions:

<augment_code_snippet path="README.md" mode="EDIT">
```markdown
## Migration from official CLI

If you have the official CLI installed:

```bash
# Remove official version
npm uninstall -g @neutralinojs/neu

# Install enhanced version
npm install -g @yourusername/neu

# Verify installation
neu --version
```

All existing projects will continue to work without changes.
```
</augment_code_snippet>

### Package managers handle this automatically
Since both packages provide the same `neu` binary, npm will automatically replace the old one when installing your version. The global binary location will be updated to point to your package.

Your enhanced features (custom `--owner` and `--branch` options) will then be available in all `neu` commands!
